# November 18, 2026: the northeast corner of Litchfield County (Winsted, Barkhamsted and Riverton, Colebrook, Norfolk,
# New Hartford) and Collinsville in Canton, next door. Region ct drawn at random by choose.py.
# Facts come only from sources opened in this session: Wikipedia read as raw text (tools/wiki_raw.py), the CT DEEP park
# pages (ctparks.com and portal.ct.gov, including the DEEP forestry letterbox page for American Legion State Forest),
# the Peoples State Forest Nature Museum's own site, the Canton Historical Museum's site, ConnecticutHistory.org,
# Buildings of New England and the Lakeville Journal. Where a manager's page could not be read the access note says so.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]

BATCH={'key':'ct_fhib','label':'Winsted, Riverton, Norfolk and Collinsville, Connecticut','added':'2026-11-18 06:03'}

PSF=L('CT DEEP: Peoples State Forest','https://ctparks.com/parks/peoples-state-forest')
ALSF=L('CT DEEP: American Legion State Forest','https://ctparks.com/parks/american-legion-state-forest')
